s","authors":[{"__typename":"AuthorByline","authorConnection":{"__typename":"AuthorBylineAuthorConnection","edges":[{"__typename":"AuthorBylineAuthorEdge","node":{"__typename":"Author","title":"Neale Mahoney","author_title":null}}]}},{"__typename":"AuthorByline","authorConnection":{"__typename":"AuthorBylineAuthorConnection","edges":[{"__typename":"AuthorBylineAuthorEdge","node":{"__typename":"Author","title":"Abigail Sanchez","author_title":""}}]}}]},"display_options":{"__typename":"ArticleDisplayOptions","template":"standard","home_page_imageConnection":{"__typename":"SysAssetConnection","edges":[]}},"taxonomy":{"__typename":"TimeTaxonomy","primary_sectionConnection":{"__typename":"TimeTaxonomyPrimarySectionConnection","edges":[{"__typename":"TimeTaxonomyPrimarySectionEdge","node":{"__typename":"Section","title":"Ideas","url":"/section/ideas/"}}],"totalCount":1},"primary_topicConnection":{"__typename":"TimeTaxonomyPrimaryTopicConnection","edges":[{"__typename":"TimeTaxonomyPrimaryTopicEdge","node":{"__typename":"Topic","title":"Economics","url":"/tag/economics/"}}],"totalCount":1}}}},{"__typename":"HomepageVoicesEdge","node":{"__typename":"Article","title":"The Cornell 7 Case Demands More Than Outrage","url":"/article/2026/10/09/the-cornell-7-case-demands-more-than-outrage/","overrides":{"__typename":"ArticleOverrides","short_title":"The Cornell 7 Case Demands More Than Outrage","description":"“National outrage helps shake people up enough to pay attention,” writes Tarana Burke. “But culture won't shift just because we change laws and elect better politicians.”"},"publication_dates":{"__typename":"PublicationDates","published":"2026-10-09T11:00:03.000Z"},"system":{"__typename":"EntrySystemField","uid":"blt1ac7fca3d707b1b9","publish_details":{"__typename":"SystemPublishDetails","time":"2026-10-09T15:30:50.331Z"}},"featured_media":{"__typename":"FeaturedMedia","image_caption":"The Chi Pi fraternity house on the campus at Cornell University in Ithaca, New York on October 2, 2026.","image_credit":"Matt Burkhartt—AFP/Getty Images","media_id":"","media_type":"medium-jw","media_orientation":"vertical","video":[{"mediaid":"y5lJqp92","title":"MeToo Founder On Why Survivors See Themselves In Cornell 7 Case","image":"https://cdn.jwplayer.com/v2/media/y5lJqp92/poster.jpg?width=720","link":"https://cdn.jwplayer.com/previews/y5lJqp92","description":"MeToo founder, Tarana Burke, explains why the Cornell 7 case has resonated so deeply with survivors, saying that you don’t have to have the exact same experience to recognize what it feels like to lose control over your body.\n\nThe case, dubbed the “Cornell 7”, centers on allegations from a Cornell student identified as Jane Doe, who claims she was raped by seven Chi Phi fraternity members in 2024.\n\nAfter the Tompkins County District Attorney’s Office initially declined to prosecute, the investigation was reopened, with New York Attorney General Letitia James appointed as special prosecutor.\n\nFor survivors, Burke says, the response to Jane Doe’s story reflects the same recognition behind MeToo: “We know it in our bones, we know it in our spirits, in our bodies, we know it in our lived reality what this is.”","pubdate":1791557619,"duration":67,"tracks":[{"file":"https://cdn.jwplayer.com/tracks/3lYURPZW.srt","kind":"captions","label":"English(US)_v","language":"en-US"},{"file":"https://cdn.jwplayer.com/strips/y5lJqp92-120.vtt","kind":"thumbnails"}]}],"video_credit":"","show_video":true,"imageConnection":{"__typename":"SysAssetConnection","edges":[{"__typename":"SysAssetEdge","node":{"__typename":"SysAsset","url":"https://gcp-na-images.contentstack.com/v3/assets/bltea6093859af6183b/blt67a9f97acf83a469/6ac805239a32fd237fba123d/Cornell-7-Outrage.jpg?branch=production","description":null,"metadata":null,"title":"Cornell-7-Outrage.jpg","dimension":{"__typename":"SysAssetDimension","height":683,"width":1024},"system":{"__typename":"SysAssetSystemField","extensionConnection":{"__typename":"SysExte